package com.bankpli.javabank.swift;import java.math.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;import org.springframework.stereotype.Service;
@Service public class FxService {private final Map<String,BigDecimal>rates=new ConcurrentHashMap<>(Map.of("USD/EUR",new BigDecimal("0.9200"),"EUR/USD",new BigDecimal("1.0870"),"USD/GBP",new BigDecimal("0.7900"),"GBP/USD",new BigDecimal("1.2658")));public BigDecimal rate(String from,String to){if(from.equals(to))return BigDecimal.ONE;BigDecimal rate=rates.get(from.toUpperCase()+"/"+to.toUpperCase());if(rate==null)throw new IllegalArgumentException("Unsupported currency pair");return rate;}public BigDecimal convert(BigDecimal amount,String from,String to){return amount.multiply(rate(from,to)).setScale(2,RoundingMode.HALF_UP);}public Map<String,BigDecimal>rates(){return Map.copyOf(rates);}}
